from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class LnbtsTddParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        has_bbmods = isinstance(self.enb_ent_config.get('bbmods'), list)
        if not has_bbmods:
            if not execution_config['is_fsm4'] and self.enb_ent_config['cells_count'] > 3:
                self.set_parameter('actFlexBbUsage', 'true')

        if self.enb_ent_config['is_ecpri']:
            self.set_struct_parameter('dlSectorBFWeightCusProf', 'dlSectorBFWeightProfName', 'customized profile 1')
            self.set_struct_parameter('dlSectorBFWeightCusProf', 'modulusOfWeighforAntGrp0', 100)
            self.set_struct_parameter('dlSectorBFWeightCusProf', 'modulusOfWeighforAntGrp1', 100)
            self.set_struct_parameter('dlSectorBFWeightCusProf', 'modulusOfWeighforAntGrp2', 100)
            self.set_struct_parameter('dlSectorBFWeightCusProf', 'modulusOfWeighforAntGrp3', 100)
            self.set_struct_parameter('dlSectorBFWeightCusProf', 'phaseOfWeighforAntGrp0', 0)
            self.set_struct_parameter('dlSectorBFWeightCusProf', 'phaseOfWeighforAntGrp1', 0)
            self.set_struct_parameter('dlSectorBFWeightCusProf', 'phaseOfWeighforAntGrp2', 0)
            self.set_struct_parameter('dlSectorBFWeightCusProf', 'phaseOfWeighforAntGrp3', 0)
